M(rgn, r"""
public static int harvested(@WLD@ w, String wn, @PKG@.ZIndex ix, @V3I@ b, String id, String cs) {
  if (!@PKG@.ZCfg.REGEN_ON || DIR == null || !"StageFinal".equals(cs)) return 1;
  String t = @PKG@.ZRules.resType(ix, wn, b.x, b.y, b.z, id);
  if (!"crops".equals(t)) return 1;
  long ms = delay(t);
  if (ms < 0L) return 1;
  if (wn == null || !wn.matches("[A-Za-z0-9_.-]{1,64}")) return 1;
  String cur = @PKG@.ZEng.blockAt(w, b.x, b.y, b.z);
  if (cur == null || cur.equals("Empty") || !@PKG@.ZDep.idOk(cur)) return 1;
  int[] st = @PKG@.ZEng.stateAt(w, b.x, b.y, b.z);
  String ph = @PKG@.ZEng.stageKey(cur);
  @PKG@.ZRw r = rw(wn, true);
  if (r == null) return 1;
  Long k = Long.valueOf(@PKG@.ZDep.key(b.x, b.y, b.z));
  if (r.dep.containsKey(k) || r.tpos.containsKey(k)) return 2;
  if (r.dep.size() + r.trees.size() >= @PKG@.ZCfg.MAXDEP) early(r);
  long now = @PKG@.ZDep.now();
  @PKG@.ZDep d = new @PKG@.ZDep(b.x, b.y, b.z, cur, t, ph, st == null ? 0 : st[0], now + ms);
  d.state = 3;   // fixer: the Use event also fires when the harvest fails - the pass checks once after 1 s (still ripe = dropped), no placeholder write
  d.next = now + 1000L;
  if (r.dep.putIfAbsent(k, d) != null) return 2;
  if (!r.append(d.line())) { r.dep.remove(k, d); return 3; }
  HARVESTED.incrementAndGet();
  return 0;
}""")
